<?php
namespace App\Services\Tenancy;
use App\Enums\{BranchStatus,BusinessType,CompanyStatus,MembershipStatus,ProvisioningAttemptStatus,ProvisioningStep,TenantStatus}; use App\Models\Central\{ProvisioningAttempt,Tenant,TenantMembership}; use App\Models\Tenant\{Branch,Company,CompanyUserAccess,TenantAuditLog}; use App\Services\PlatformAuditService; use App\Services\TenantStatusTransitionService; use App\Tenancy\TenantContextManager; use Illuminate\Contracts\Cache\LockTimeoutException; use Illuminate\Support\Facades\{Artisan,Cache,DB}; use RuntimeException; use Throwable;
final class TenantProvisioner {
 public function __construct(private CreateTenantDatabase $createDatabase,private TenantContextManager $context,private TenantFoundationSeeder $seed,private TenantDatabaseName $names,private TenantStatusTransitionService $transitions,private PlatformAuditService $audit){}
 public function provision(Tenant $tenant,?int $actorId=null,?string $requestId=null):ProvisioningAttempt { try{$lock=Cache::lock('tenant-provisioning:'.$tenant->id,120); if(!$lock->get())throw new RuntimeException('Tenant provisioning is already in progress.');}catch(LockTimeoutException){throw new RuntimeException('Tenant provisioning is already in progress.');} try { return $this->run($tenant->fresh(),$actorId,$requestId); } finally {$lock->release();$this->context->clear();} }
 private function run(Tenant $tenant,?int $actorId,?string $requestId):ProvisioningAttempt { if(!in_array($tenant->status,[TenantStatus::Pending,TenantStatus::Provisioning,TenantStatus::ProvisioningFailed],true))throw new RuntimeException('Tenant is not eligible for provisioning.'); $attempt=$this->attempt($tenant,$actorId,$requestId); try { if($tenant->status!==TenantStatus::Provisioning)$this->transitions->transition($tenant,TenantStatus::Provisioning,null,null); $this->step($attempt,ProvisioningStep::DatabaseCreated,function()use($tenant){($this->createDatabase)($tenant);}); $this->context->initialize($tenant); $this->step($attempt,ProvisioningStep::Migrated,fn()=>Artisan::call('migrate',['--database'=>'tenant','--path'=>'database/migrations/tenant','--force'=>true])); $this->step($attempt,ProvisioningStep::FoundationSeeded,fn()=>($this->seed)($tenant->owner_user_id)); $company=null; $this->step($attempt,ProvisioningStep::DefaultCompany,function()use(&$company){$company=Company::query()->firstOrCreate(['code'=>'DEFAULT'],['legal_name'=>'Default Company','display_name'=>'Default Company','business_type'=>BusinessType::GeneralSme,'country_code'=>'BD','base_currency_code'=>'BDT','timezone'=>'Asia/Dhaka','date_format'=>'Y-m-d','number_format'=>'1,234.56','status'=>CompanyStatus::Active,'is_default'=>true]); if($company->status===CompanyStatus::Archived)throw new RuntimeException('Default company is archived.');}); $company??=Company::query()->where('is_default',true)->firstOrFail(); $this->step($attempt,ProvisioningStep::DefaultBranch,function()use($company){Branch::query()->firstOrCreate(['company_id'=>$company->id,'code'=>'HEAD_OFFICE'],['name'=>'Head Office','timezone'=>$company->timezone,'status'=>BranchStatus::Active,'is_default'=>true]);}); $this->step($attempt,ProvisioningStep::OwnerAccess,function()use($tenant,$company){$membership=TenantMembership::query()->where('tenant_id',$tenant->id)->where('user_id',$tenant->owner_user_id)->where('status',MembershipStatus::Active)->first(); if(!$membership)throw new RuntimeException('Tenant owner membership is not active.'); CompanyUserAccess::query()->firstOrCreate(['company_id'=>$company->id,'user_id'=>$tenant->owner_user_id],['tenant_membership_id'=>$membership->id,'access_level'=>'owner','status'=>'active']); TenantAuditLog::query()->create(['actor_user_id'=>$tenant->owner_user_id,'company_id'=>$company->id,'action'=>'company.owner_access_created','created_at'=>now()]);}); $this->step($attempt,ProvisioningStep::Completed,fn()=>null); $attempt->update(['status'=>ProvisioningAttemptStatus::Completed,'current_step'=>ProvisioningStep::Completed->value,'completed_at'=>now()]); $this->transitions->transition($tenant->fresh(),TenantStatus::Trialing); $this->audit->record('tenant.provisioned',null,$tenant,$tenant,null,['attempt'=>$attempt->attempt_number]); return $attempt->fresh(); } catch(Throwable $e) {$attempt->update(['status'=>ProvisioningAttemptStatus::Failed,'error_code'=>'provisioning_failed','sanitized_error_message'=>$this->sanitize($e->getMessage()),'failed_at'=>now()]); $tenant->refresh();if($tenant->status===TenantStatus::Provisioning)$this->transitions->transition($tenant,TenantStatus::ProvisioningFailed);throw $e;} }
 private function attempt(Tenant $tenant,?int $actor,?string $request):ProvisioningAttempt{$last=$tenant->provisioningAttempts()->latest('attempt_number')->first();if($last?->status===ProvisioningAttemptStatus::InProgress)throw new RuntimeException('Tenant provisioning is already in progress.');return ProvisioningAttempt::query()->create(['tenant_id'=>$tenant->id,'attempt_number'=>($last?->attempt_number??0)+1,'status'=>ProvisioningAttemptStatus::InProgress,'completed_steps'=>$last?->completed_steps??[],'initiated_by_user_id'=>$actor,'request_id'=>$request,'started_at'=>now()]);}
 private function step(ProvisioningAttempt $attempt,ProvisioningStep $step,callable $work):void{$done=$attempt->completed_steps??[];if(in_array($step->value,$done,true))return;$attempt->update(['current_step'=>$step->value]);$work();$done[]=$step->value;$attempt->update(['completed_steps'=>array_values(array_unique($done))]);}
 private function sanitize(string $message):string{$message=preg_replace('/(password|secret|token|mysql:\/\/)[^\s]*/i','$1 [redacted]',$message)??'Provisioning failed.';return mb_substr($message,0,500);}
}
